class KDNode:
    def __init__(self, point, left=None, right=None):
        self.point = point  # k-dimensional point
        self.left = left
        self.right = right

def nearest_neighbor(node, point, depth=0, best=None):
    if node is None:
        return best

    k = len(point)
    axis = depth % k

    if best is None or distance(point, node.point) < distance(point, best):
        best = node.point

    if point[axis] < node.point[axis]:
        nearer, farther = node.left, node.right
    else:
        nearer, farther = node.right, node.left

    best = nearest_neighbor(nearer, point, depth + 1, best)

    if abs(point[axis] - node.point[axis]) < distance(point, best):
        best = nearest_neighbor(farther, point, depth + 1, best)

    return best
